<?php $pageTitle='Dashboard Registrasi'; require_once 'config/database.php'; require_once 'config/auth.php'; require_login();
$total=(int)$pdo->query("SELECT COUNT(*) FROM patients")->fetchColumn();
$today=(int)$pdo->query("SELECT COUNT(*) FROM visits WHERE DATE(created_at)=CURDATE()")->fetchColumn();
$waiting=(int)$pdo->query("SELECT COUNT(*) FROM visits WHERE DATE(created_at)=CURDATE() AND status IN ('Terdaftar','Menunggu','Dipanggil')")->fetchColumn();
$apptToday=(int)$pdo->query("SELECT COUNT(*) FROM appointments WHERE appointment_date=CURDATE() AND status IN ('confirmed','pending')")->fetchColumn();
$review=(int)$pdo->query("SELECT COUNT(*) FROM patients WHERE duplicate_flag=1")->fetchColumn();
$recent=$pdo->query("SELECT v.*,p.name,p.medical_record_no FROM visits v JOIN patients p ON p.id=v.patient_id ORDER BY v.id DESC LIMIT 7")->fetchAll();
$upcoming=$pdo->query("SELECT a.*,p.name FROM appointments a JOIN patients p ON p.id=a.patient_id WHERE a.appointment_date>=CURDATE() ORDER BY a.appointment_date,a.appointment_time LIMIT 6")->fetchAll();
$clinicLoad=$pdo->query("SELECT clinic,COUNT(*) total FROM visits WHERE DATE(created_at)=CURDATE() GROUP BY clinic ORDER BY total DESC LIMIT 6")->fetchAll();
include 'partials/header.php'; ?>
